class Solution:
    def longestUniform(self, s: str, k: int) -> int:
        n, best = len(s), 0
        for i in range(n):
            count, top = [0] * 26, 0
            for j in range(i, n):
                x = ord(s[j]) - 65
                count[x] += 1
                top = max(top, count[x])
                if j - i + 1 - top > k:
                    break
                best = max(best, j - i + 1)
        return best

