class Solution {
    public int longestUniform(String s, int k) {
        int n = s.length(), best = 0;
        for (int i = 0; i < n; i++) {
            int[] count = new int[26];
            int top = 0;
            for (int j = i; j < n; j++) {
                top = Math.max(top, ++count[s.charAt(j) - 'A']);
                if (j - i + 1 - top > k) break;
                best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }
}

