        int t = 0;
        for (int c : count) t = Math.max(t, c);
        return t;
    }

    public int longestUniform(String s, int k) {
        int[] count = new int[26];
        int left = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'A']++;
            while (i - left + 1 - top(count) > k) count[s.charAt(left++) - 'A']--;
            best = Math.max(best, i - left + 1);
        }
        return best;
    }
}

